  slab(g, 8, 4, 19, 9, 24, WHITE_CONCRETE); // bathroom
  slab(g, 8, 2, 6, 5, 6, SPRUCE_PLANKS); // bay
  slab(g, 12, 2, 8, 13, 29, BIRCH_PLANKS, { holes: [[13, 12, 18, 13, 12, 20], [2, 12, 19, 3, 12, 23]] });
