  wallLine(g, 10, 8, 10, 24, 5, 7, "inner", { open: [[10, 5, 12, 10, 7, 13], [10, 5, 21, 10, 6, 21]] });
  wallLine(g, 10, 8, 10, 24, 9, 11, "inner", { open: [[10, 9, 12, 10, 10, 12], [10, 9, 21, 10, 10, 21]] });
