  stairFlight(g, 13, 13, 5, 3, "south", DARK_OAK_STAIRS);
  stairFlight(g, 13, 17, 9, 3, "south", DARK_OAK_STAIRS);
  stairFlight(g, 13, 15, 1, 3, "south", DARK_OAK_STAIRS);
